use std::io

fn is_int(tok: string) -> bool {
    let mut digits = 0
    let mut i = 0
    for c in tok.chars() {
        if c == '-' && i == 0 {
            // sign
        } else if c >= '0' && c <= '9' {
            digits = digits + 1
        } else {
            return false
        }
        i = i + 1
    }
    digits > 0
}

fn eval(line: string) -> string {
    let mut stack: Vec<int> = Vec::new()
    for tok in line.split_whitespace() {
        if tok == "+" || tok == "-" || tok == "*" || tok == "/" {
            if stack.len() < 2 {
                return "error: underflow"
            }
            let b = stack.pop() ?? 0
            let a = stack.pop() ?? 0
            if tok == "+" {
                stack.push(a + b)
            } else if tok == "-" {
                stack.push(a - b)
            } else if tok == "*" {
                stack.push(a * b)
            } else {
                if b == 0 {
                    return "error: divzero"
                }
                stack.push(a / b)
            }
        } else if is_int(tok) {
            stack.push(tok.parse::<int>() ?? 0)
        } else {
            return "error: token"
        }
    }
    if stack.len() != 1 {
        return "error: leftover"
    }
    stack[0].to_string()
}

fn main() {
    let t = io::read_to_string() ?? ""
    for line in t.lines() {
        if line.trim().len() == 0 {
            continue
        }
        println(eval(line))
    }
}

